public static char[] toCharArray(final CharSequence source) {
    final int len = StringUtils.length(source);
    if (len == 0) {
        return ArrayUtils.EMPTY_CHAR_ARRAY;
    }
    if (source instanceof String) {
        return ((String) source).toCharArray();
