    int pos = offset;

    // loop around the entire buffer
    while (pos >= 0 && pos < count) {
        // find next token
        pos = readNextToken(srcChars, pos, count, buf, tokenList);

        // handle case where end of string is a delimiter
        if (pos >= count) {
            addToken(tokenList, StringUtils.EMPTY);
        }
    }
    return tokenList;
