        final Method accessibleMethod = getAccessibleMethod(method);
        if (accessibleMethod != null && (bestMatch == null || MemberUtils.compareMethodFit(
                    accessibleMethod,
                    bestMatch,
                    parameterTypes) < 0)) {
            bestMatch = accessibleMethod;
